    def test_paper_parsing(self):
        # Using real PDF generated by fpdf2
        fixture_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "fixtures", "test_paper.pdf"))
        
        result = parse_pdf(fixture_path)
        
        self.assertIn("content_hash", result)
        self.assertIn("paper_date", result)
        self.assertTrue(len(result["sections"]) > 0)
        # Check that Abstract is somewhere in the first section's text or title
        first_section_text = result["sections"][0]["title"] + "\\n" + result["sections"][0]["text"]
        self.assertIn("Abstract", first_section_text)
        
        # Verify tables extraction
        has_metric = False
        if result.get("tables"):
            for row in result["tables"][0]["content"]:
                if "Metric" in row or any("Metric" in col for col in row):
                    has_metric = True
        self.assertTrue(has_metric, "Table extraction failed or missed 'Metric' column")
        
