    def test_repo_indexer(self):
        # Create a dummy repo structure
        os.makedirs("test_repo", exist_ok=True)
        with open("test_repo/main.py", "w") as f:
            f.write("import argparse\nimport hydra\nparser = argparse.ArgumentParser()\nparser.add_argument('--epochs')\n")
        with open("test_repo/requirements.txt", "w") as f:
            f.write("torch\n")
        with open("test_repo/README.md", "w") as f:
            f.write("Run this:\npython main.py --epochs 10\n")
            
        with open("test_repo/config.yaml", "w") as f:
            f.write("epochs: 10\nhydra:\n  run:\n    dir: .\n")
            
        # Create a git repository to test git date extraction
        import subprocess
        subprocess.check_call(["git", "init"], cwd="test_repo")
        subprocess.check_call(["git", "config", "user.email", "test@test.com"], cwd="test_repo")
        subprocess.check_call(["git", "config", "user.name", "Test"], cwd="test_repo")
        subprocess.check_call(["git", "add", "."], cwd="test_repo")
        subprocess.check_call(["git", "commit", "-m", "init"], cwd="test_repo")
        
        # Get actual commit date to assert
        commit_date = subprocess.check_output(["git", "log", "-1", "--format=%cI"], cwd="test_repo", text=True).strip()
            
        result = index_repository("test_repo")
        
        self.assertIn("repo_hash", result)
        self.assertIn("repository_date", result)
        self.assertIsNotNone(result["repository_date"])
        self.assertIn("main.py", result["entry_scripts"])
        self.assertIn("main.py", result["argparse_interfaces"])
        self.assertIn("--epochs", result["argparse_interfaces"]["main.py"])
        self.assertIn("requirements.txt", result["dependencies"])
        self.assertIn("python main.py --epochs 10", result["readme_commands"])
        self.assertIn("config.yaml", result["config_files"])
        self.assertTrue(result["uses_hydra"])
        self.assertEqual(result["repository_date"], commit_date)
        
        import shutil
        shutil.rmtree("test_repo", ignore_errors=True)
        
    @patch('app.intelligence.llm.get_llm_client')
    def test_claim_extraction(self, mock_get_client):
        mock_client = MagicMock()
        mock_client.chat.completions.create.return_value = ClaimExtractionArtifact(
            assessment_id="test_assessment",
            claims=[{
                "claim_id": "c1",
                "experiment": "Exp 1",
                "dataset": "CIFAR",
                "metric": "Accuracy",
                "value": 0.95,
                "page": 1,
                "evidence": {"value": {"quote": "accuracy is 0.95", "page": 1}}
            }],
            settings={
                "epochs": 10,
                "evidence": {"epochs": {"quote": "we trained for 10 epochs", "page": 2}}
            }
        )
        mock_get_client.return_value = mock_client
        
        # Call extraction
        sections = [{"title": "Test Title", "text": "some text", "page": 1}]
        result = extract_claims(sections, "hash123")
        
        self.assertEqual(len(result.claims), 1)
        self.assertEqual(result.claims[0].value, 0.95)
        self.assertEqual(result.claims[0].evidence["value"].quote, "accuracy is 0.95")
        
        # Test caching
        self.assertIn("claims_hash123", _LLM_CACHE)
        
        # Change mock to see if cache is hit
        mock_client.chat.completions.create.side_effect = Exception("Should not be called")
        cached_result = extract_claims(sections, "hash123")
        self.assertEqual(cached_result.claims[0].value, 0.95)
        
    @patch('app.intelligence.llm.get_llm_client')
    @patch('app.intelligence.llm.time.sleep')
    def test_claim_extraction_chunking(self, mock_sleep, mock_get_client):
        # Create a large paper with multiple sections that exceed the 8000 char limit
        # This will test chunking, merging, and deduplication
        sections = []
        for i in range(10):
            # Each section is 1000 chars of 'A'
            sections.append({
                "title": f"Section {i}",
                "text": "A" * 1000,
                "page": i
            })
        
        # This is 10,000 chars total, so it should be split into 2 chunks
        
        mock_client = MagicMock()
        # Side effect to return different results for each chunk
        def side_effect(*args, **kwargs):
            if mock_client.chat.completions.create.call_count == 1:
                return ClaimExtractionArtifact(
                    assessment_id="test",
                    claims=[{
                        "claim_id": "c1", "experiment": "Exp 1", "dataset": "Data 1", "split": "test", "metric": "Acc", "value": 0.9, "page": 1,
                        "evidence": {"value": {"quote": "acc 0.9", "page": 1}}
                    }],
                    settings={"epochs": 10, "evidence": {"epochs": {"quote": "10 epochs", "page": 1}}}
                )
            else:
                return ClaimExtractionArtifact(
                    assessment_id="test",
                    claims=[
                        # Duplicate claim (should be merged/deduplicated)
                        {
                            "claim_id": "c2", "experiment": "Exp 1", "dataset": "Data 1", "split": "test", "metric": "Acc", "value": 0.9, "page": 1,
                            "evidence": {"value": {"quote": "acc 0.9", "page": 1}}
                        },
                        # New claim
                        {
                            "claim_id": "c3", "experiment": "Exp 2", "dataset": "Data 2", "split": "val", "metric": "F1", "value": 0.8, "page": 2,
                            "evidence": {"value": {"quote": "f1 0.8", "page": 2}}
                        }
                    ],
                    settings={"hardware": "V100", "evidence": {"hardware": {"quote": "used V100", "page": 2}}}
                )
        
        mock_client.chat.completions.create.side_effect = side_effect
        mock_get_client.return_value = mock_client
        
        result = extract_claims(sections, "chunkhash123")
        
        # Verify 2 chunks were processed
        self.assertEqual(mock_client.chat.completions.create.call_count, 2)
        # Verify sleep was called for pacing between chunks
        mock_sleep.assert_called_once_with(25)
        
        # Verify claims are merged and deduplicated (Exp 1 appears twice, so 2 unique claims total)
        self.assertEqual(len(result.claims), 2)
        
        # Verify settings are merged
        self.assertEqual(result.settings.epochs, 10)
        self.assertEqual(result.settings.hardware, "V100")
        
        # Verify missing fields remain None
        self.assertIsNone(result.settings.seeds)
        
        # Verify paper-hash caching works (subsequent call uses cache)
        mock_client.chat.completions.create.call_count = 0
        cached_result = extract_claims(sections, "chunkhash123")
        self.assertEqual(mock_client.chat.completions.create.call_count, 0)
        self.assertEqual(len(cached_result.claims), 2)
        
    @patch('app.intelligence.llm.get_llm_client')
    @patch('app.intelligence.llm.time.sleep')
    def test_claim_extraction_rate_limit_failure_and_resume(self, mock_sleep, mock_get_client):
        from app.intelligence.llm import extract_claims, RateLimitTooLongException
        from app.schemas.artifacts import ClaimExtractionArtifact, ClaimData, ExperimentSettings
        import openai
        
        sections = [
            {"title": "Section 1", "text": "A" * 9000, "page": 1},
            {"title": "Section 2", "text": "B" * 9000, "page": 2}
        ]
        
        mock_client = MagicMock()
        
        # First chunk succeeds, second chunk hits a long rate limit
        mock_client.chat.completions.create.side_effect = [
            ClaimExtractionArtifact(
                assessment_id="test",
                claims=[
                    ClaimData(claim_id="c1", experiment="e1", metric="m1", value=1.0, page=1, evidence={"e": {"quote": "q", "page": 1}})
                ],
                settings=ExperimentSettings(evidence={})
            ),
            Exception("Rate limit reached. Please try again in 5m20s.")
        ]
        mock_get_client.return_value = mock_client
        
        hash_val = "ratelimit_hash_123"
        
        # Test that extraction explicitly fails when the second chunk fails
        with self.assertRaises(RateLimitTooLongException) as context:
            extract_claims(sections, hash_val)
            
        self.assertTrue("Required wait is" in str(context.exception))
        
        # Verify first chunk was cached but final artifact was not created
        from app.intelligence.llm import _LLM_CACHE
        self.assertIn(f"claims_{hash_val}_chunk_0", _LLM_CACHE)
        self.assertNotIn(f"claims_{hash_val}", _LLM_CACHE)
        
        # Second run: Should resume and NOT call the LLM for chunk 0
        mock_client.chat.completions.create.side_effect = [
            ClaimExtractionArtifact(
                assessment_id="test",
                claims=[
                    ClaimData(claim_id="c2", experiment="e2", metric="m2", value=2.0, page=2, evidence={"e": {"quote": "q2", "page": 2}})
                ],
                settings=ExperimentSettings(evidence={})
            )
        ]
        
        # Reset mock call count
        mock_client.chat.completions.create.reset_mock()
        
        result = extract_claims(sections, hash_val)
        
        # The LLM should only have been called ONCE for chunk 1, since chunk 0 was cached
        self.assertEqual(mock_client.chat.completions.create.call_count, 1)
        
        # Both claims should be present in the final result
        self.assertEqual(len(result.claims), 2)
        self.assertEqual(result.claims[0].claim_id, "c1")
        self.assertEqual(result.claims[1].claim_id, "c2")

