    @patch("app.intelligence.parser.urllib.request.urlopen")
    def test_arxiv_resolution(self, mock_urlopen):
        # Setup mock network response
        import io
        from app.intelligence.parser import resolve_paper_source
        from app.core.config import settings
        import urllib.error
        
        mock_response = MagicMock()
        mock_response.read.return_value = b"%PDF-1.4 Mock arXiv PDF Content"
        mock_response.__enter__.return_value = mock_response
        mock_urlopen.return_value = mock_response

        cache_dir = os.path.join(settings.STORAGE_DIR, "_arxiv_test_cache")
        
        # 1. Test successful resolution of 'arxiv:1803.03635'
        path1 = resolve_paper_source("arxiv:1803.03635", cache_dir)
        self.assertTrue(path1.endswith("1803.03635.pdf"))
        self.assertTrue(os.path.exists(path1))
        
        # Clean up
        os.remove(path1)

        # 2. Test successful resolution of '1803.03635'
        path2 = resolve_paper_source("1803.03635", cache_dir)
        self.assertTrue(path2.endswith("1803.03635.pdf"))
        self.assertTrue(os.path.exists(path2))
        
        # Clean up
        os.remove(path2)
        
        # 3. Test successful resolution of 'https://arxiv.org/abs/1803.03635'
        path3 = resolve_paper_source("https://arxiv.org/abs/1803.03635", cache_dir)
        self.assertTrue(path3.endswith("1803.03635.pdf"))
        self.assertTrue(os.path.exists(path3))
        
        # Clean up
        os.remove(path3)
        
        # 4. Test failure on invalid arXiv ID simulating HTTP 404
        mock_urlopen.side_effect = urllib.error.URLError("HTTP Error 404: Not Found")
        with self.assertRaises(ValueError):
            resolve_paper_source("arxiv:9999.99999", cache_dir)
            
    @patch("app.intelligence.parser.ssl.create_default_context")
    @patch("app.intelligence.parser.urllib.request.urlopen")
    def test_arxiv_ssl_verification(self, mock_urlopen, mock_ssl_context):
        import certifi
        import io
        import urllib.error
        from app.intelligence.parser import resolve_paper_source
        from app.core.config import settings

        mock_response = MagicMock()
        mock_response.read.return_value = b"%PDF-1.4 Mock arXiv PDF Content"
        mock_response.__enter__.return_value = mock_response
        mock_urlopen.return_value = mock_response
        
        mock_ctx = MagicMock()
        mock_ssl_context.return_value = mock_ctx

        cache_dir = os.path.join(settings.STORAGE_DIR, "_arxiv_test_cache_ssl")
        
        # Test successful resolution triggers correct SSL configuration
        path1 = resolve_paper_source("arxiv:1803.03635", cache_dir)
        
        mock_ssl_context.assert_called_once_with(cafile=certifi.where())
        
        # Verify the context is actually passed to urlopen
        called_args, called_kwargs = mock_urlopen.call_args
        self.assertIn('context', called_kwargs)
        self.assertEqual(called_kwargs['context'], mock_ctx)
        
        # Clean up
        if os.path.exists(path1):
            os.remove(path1)

    @patch("app.intelligence.parser.urllib.request.urlopen")
    @patch("app.pipeline.stages_ws4.parse_pdf")
    def test_paper_parsing_stage_with_arxiv(self, mock_parse_pdf, mock_urlopen):
        # 5. Test PaperParsingStage directly receives the downloaded PDF path
        mock_parse_pdf.return_value = {
            "content_hash": "mockhasharxiv",
            "paper_date": "2018-03-01T00:00:00Z",
            "sections": [],
            "tables": []
        }
        mock_response = MagicMock()
        mock_response.read.return_value = b"%PDF-1.4 Mock arXiv PDF Content"
        mock_response.__enter__.return_value = mock_response
        mock_urlopen.return_value = mock_response

        # Setup Assessment with arXiv source
        import uuid
        from app.db.models import Assessment
        from app.pipeline.stages_ws4 import PaperParsingStage
        
        assessment_id = str(uuid.uuid4())
        assessment = Assessment(
            id=assessment_id,
            paper_source="1803.03635",
            paper_input_type="url",
            repository_source="https://github.com/test/repo",
            repository_input_type="url"
        )
        
        mock_db = MagicMock()
        mock_query = MagicMock()
        mock_filter = MagicMock()
        mock_db.query.return_value = mock_query
        mock_query.filter.return_value = mock_filter
        mock_filter.first.return_value = assessment

        # Execute Stage
        stage = PaperParsingStage()
        # Mock create_db_session to use test DB
        stage._create_db_session = MagicMock(return_value=mock_db)
        
        # Mock save_artifact to avoid DB schema errors
        mock_out = MagicMock()
        mock_out.type = "PaperDocumentArtifact"
        stage.save_artifact = MagicMock(return_value=mock_out)
        
        output_artifacts = stage.execute(assessment_id, [])

        self.assertEqual(len(output_artifacts), 1)
        self.assertEqual(output_artifacts[0].type, "PaperDocumentArtifact")
        
        # Verify parse_pdf was called with the cached arxiv file path, not '1803.03635' directly
        called_path = mock_parse_pdf.call_args[0][0]
        self.assertTrue(called_path.endswith("1803.03635.pdf"))
        self.assertNotEqual(called_path, "1803.03635")


